export function buildGoldenPackage(
  input: GeneratedPackageDraftInput
): GeneratedPackage {
  return finalizeGeneratedPackageDraft(buildGeneratedPackageDraft(input)).finalPkg;
}

export type GoldenBuildInput = (typeof GOLDEN_BUILD_INPUTS)[number];

